import json
data = json.loads(context)
best = {}
for row in data:
    key = (row['record_date'], row['src_line_nbr'])
    if key not in best or row['version'] > best[key]['version']:
        best[key] = row
deposits = 0
withdrawals = 0
for row in best.values():
    acct = row['account_type']
    amount = int(row['open_today_bal'])
    if acct == 'Total TGA Deposits (Table II)':
        deposits += amount
    elif acct == 'Total TGA Withdrawals (Table II) (-)':
        withdrawals += amount
total = deposits - withdrawals
print(FINAL(str(total)))
